<?php
require_once dirname(__DIR__) . '/core/Controller.php'; require_once dirname(__DIR__) . '/models/User.php';
class UsersController extends Controller { private User $model; public function __construct(){ $this->model=new User(); } public function index():void{$this->requireModuleAccess('users', ['Administrator','Director','Finance Officer']);$this->view('users/index',['title'=>'Users','users'=>$this->model->all()]);} public function create():void{$this->requireRole(['Administrator']);$this->save();} public function edit():void{$this->requireRole(['Administrator']);$id=$this->sanitizeInt($_GET['id']??0);$user=$this->model->find($id);if(!$user)$this->redirect('/index.php?controller=users');$this->save($user,$id);} public function delete():void{$this->requireRole(['Administrator']);$id=$this->sanitizeInt($_GET['id']??0);if($id!==($_SESSION['user']['id']??0))$this->model->delete($id);$this->redirect('/index.php?controller=users');} private function save(?array $user=null,?int $id=null):void{if($_SERVER['REQUEST_METHOD']==='POST'){if(!$this->validateCsrf()){$this->view('users/form',['title'=>$id?'Edit User':'Create User','mode'=>$id?'edit':'create','user'=>$user,'error'=>'Invalid security token']);return;}$data=$_POST;if($id)$this->model->update($id,$data);else $this->model->create($data);$this->redirect('/index.php?controller=users');}$this->view('users/form',['title'=>$id?'Edit User':'Create User','mode'=>$id?'edit':'create','user'=>$user]);} }
